-- Mod-authored great work descriptions, ru_RU overlay.
-- Baseline in CivVAccess_GreatWorkDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_MISSING"] =
    "Для этого шедевра нет описания картины."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GIRL_WITH_PEARL_EARRING"] =
    "Картина маслом эпохи золотого века голландской живописи, один из самых любимых портретов западного искусства. Молодая женщина оборачивается через плечо, встречая ваш взгляд на простом тёмном фоне, её губы чуть приоткрыты, словно она вот-вот заговорит. На ней синий с золотом тюрбан, ткань которого спадает по спине, а у уха единственная крупная жемчужина в форме капли ловит свет."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HENRY_VIII"] =
    "Придворный портрет эпохи Тюдоров, написанный маслом, образ, который закрепил в сознании всего мира облик Генриха VIII. Король стоит лицом к вам в полный рост, широко расставив ноги, широкоплечий и грузный, одна рука покоится на кинжале у пояса. На нём усыпанный самоцветами серебряный дублет под отороченным мехом малиновым кафтаном, плоская шляпа с пером и золотые цепи; он стоит на узорчатом ковре между мраморными колоннами."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HUNTERS_IN_THE_SNOW"] =
    "Картина маслом эпохи фламандского Возрождения, зимний пейзаж, открывающийся с вершины холма. Три усталых охотника и их свора собак бредут по глубокому снегу на переднем плане, опустив головы, и единственная их добыча - одна лисица. Ниже под серовато-зелёным небом раскинулась деревня, на замёрзших прудах резвятся крошечные конькобежцы, а вдали поднимаются зубчатые вершины."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LES_DEMOISELLES"] =
    "Картина маслом раннего модернизма, полотно, положившее начало кубизму. Пять обнажённых женщин стоят и сидят в неглубоком пространстве из угловатых розовых, белых и синих плоскостей, их тела раздроблены на резкие угловатые формы. Два лица справа написаны как африканские маски, полосатые и искажённые, тогда как остальные смотрят прямо перед собой широкими миндалевидными глазами; у нижнего края стоит небольшая ваза с фруктами."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LUNCHEON"] =
    "Картина маслом французского импрессионизма, изображающая друзей, задержавшихся после трапезы. Оживлённая компания в летних нарядах теснится на балконе у реки под полосатым оранжево-белым навесом, гости беседуют, флиртуют и облокачиваются на перила; молодая женщина впереди играет с маленькой собачкой. Стол заставлен бутылками вина, бокалами и фруктами, и всё это написано тёплыми, свободными мазками залитого солнцем цвета."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MONA_LISA"] =
    "Картина маслом итальянского Возрождения на деревянной панели, вероятно, самый знаменитый портрет в мире. Женщина сидит со сложенными руками, чуть повернувшись к вам, на фоне подёрнутого дымкой пейзажа с извилистыми реками и далёкими синими горами. Её глаза встречают ваш взгляд напрямую, тем знаменитым взором, что словно следует за вами, где бы вы ни стояли. Её еле заметная полуулыбка является средоточием картины, написанная мягкими коричневыми и зелёными тонами без резких очертаний, так что её выражение будто меняется, чем дольше вы смотрите."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SUNDAY_AFTERNOON"] =
    "Картина маслом в технике пуантилизма, выстроенная целиком из крошечных точек чистого цвета. Парижане в воскресных нарядах отдыхают на солнечной лужайке у реки, прогуливаются с зонтиками от солнца, нежатся на траве и выгуливают маленьких собак, а позади на воде видны парусные лодки. Все странно неподвижны и церемонны, словно фигуры на фризе, а свет раздроблен на мерцание зелёных, оранжевых и фиолетовых крапин."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_VIEW_OF_TOLEDO"] =
    "Картина маслом испанского Возрождения, один из самых ранних чистых пейзажей в западном искусстве и необычайно мрачный. Испанский город Толедо на холме поднимается вдали под яростным грозовым небом, его серые шпили и стены освещены жутковатым серебристым светом. Зелёные холмы сбегают к реке на переднем плане, а вся сцена написана в глубоких зелёных и иссиня-чёрных тонах, в которых больше сна, чем дневного света."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_WATER_LILIES"] =
    "Картина маслом французского импрессионизма из знаменитой серии Моне, изображающей пруд в его саду в Живерни. Всё полотно занято поверхностью воды, без горизонта и берега: островки зелёных листьев кувшинок дрейфуют по синей и лиловой воде, усеянной розовыми и красными цветками. Облака и деревья проступают лишь мягкими отражениями, а мазок настолько свободен, что всё словно парит."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_STARRY_NIGHT"] =
    "Картина маслом постимпрессионизма, один из самых узнаваемых образов современного искусства. Ночное небо, полное движения, занимает большую часть полотна: звёзды пылают внутри закрученных ореолов, в углу оранжевым горит луна, а через середину неба катится огромный спиральный поток. Внизу тихая деревня с остроконечным церковным шпилем спит среди холмов, а тёмный кипарис языком пламени взмывает по левому краю, и всё это написано густыми, видимыми мазками синего и золотого."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BIRTH_OF_VENUS"] =
    "Картина итальянского Возрождения, изображающая богиню любви, выходящую из моря, один из самых знаменитых образов классического мифа. Венера стоит обнажённая на гигантской раковине-гребешке, прикрываясь руками и волной длинных золотистых волос. Слева два крылатых бога ветра подгоняют её к берегу сквозь дождь розовых роз, а справа женщина в платье, усыпанном цветами, спешит укрыть её развевающимся плащом."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BINDO_ALTOVITI"] =
    "Портрет маслом эпохи итальянского Высокого Возрождения, изображающий богатого молодого римского банкира. Красивый молодой человек с длинными золотистыми волосами и в чёрной шапочке оглядывается на вас через обнажённое плечо, одна рука прижата к груди. На нём синяя накидка поверх чёрной одежды, а его бледное лицо светится на фоне глубокого зелёного фона."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_GEORGE_DRAGON"] =
    "Картина раннего итальянского Возрождения с чопорным, сказочным очарованием. Справа закованный в латы рыцарь на вздыбленном белом коне вонзает копьё в разверстую пасть крылатого зелёного дракона с пятнистыми, похожими на мотыльковые, крыльями. Слева спокойная принцесса в длинном розовом платье держит раненое чудовище на поводке, словно домашнего питомца, перед его тёмной пещерой, а позади рыцаря собирается странная спиральная буря."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CREATION_OF_ADAM"] =
    "Фреска итальянского Возрождения с потолка Сикстинской капеллы, источник одного из самых знаменитых жестов в искусстве. Обнажённый Адам полулежит на зелёном склоне слева, безвольно вытянув одну руку, а Бог, седобородая фигура в развевающемся розовом покрове, полном ангелов, устремляется справа. Их вытянутые указательные пальцы тянутся друг к другу через небольшой зазор, миг перед искрой жизни."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GALLERY_OF_THE_LOUVRE"] =
    "Американская картина маслом, изображающая зал внутри Лувра; её написал тот самый Морзе, что позднее изобрёл телеграфный код. Парадный салон с красными стенами от пола до потолка покрыт десятками картин старых мастеров в золотых рамах, среди которых крошечная Мона Лиза. На переднем плане ученики сидят за мольбертами и копируют работы, а их учитель склонился над плечом молодой женщины, поправляя её рисунок; вдали открывается арочный коридор, ведущий в другие галереи."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_WASHINGTON_CROSSING"] =
    "Героическая американская историческая картина маслом, ставшая символом Войны за независимость. Генерал Вашингтон стоит выпрямившись на носу переполненной гребной лодки, а его солдаты гребут и отталкиваются шестами, пробиваясь через реку, забитую льдинами; стоящий позади него офицер высоко держит американский флаг. Свет зари пробивается сквозь холодную дымку, а следом плывут новые лодки, полные людей и лошадей."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ARRANGEMENT_IN_GREY"] =
    "Американская картина маслом, повсеместно известная как Мать Уистлера. Пожилая женщина в длинном чёрном платье и белом кружевном чепце сидит строго в профиль, лицом влево, сложив руки на коленях и поставив ноги на низкую скамеечку. Комната скупа и плоска: серая стена, тёмная узорчатая занавеска и единственная картина в раме; вся композиция уравновешена как этюд в сером и чёрном, в точности как и говорит название."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BREEZING_UP"] =
    "Американская реалистическая картина маслом, изображающая плавание на небольшой лодке у берегов Новой Англии. Мужчина и трое мальчиков откидываются назад в маленькой кэт-боте по имени Глостер, который кренится под крепким бризом; брызги срываются с носа, а у их ног свален дневной улов. Море под рваными облаками зеленовато и неспокойно, на горизонте видна двухмачтовая шхуна."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_A_THOUSAND_LI"] =
    "Китайский сине-зелёный пейзажный свиток, написанный на шёлке юным гением сунского двора и достигающий почти двенадцати метров в длину. Горы яркого минерально-синего и зелёного цвета встают грядой за грядой над спокойной золотистой рекой, а между склонами притаились крошечные деревни, мосты и голые деревья. Столбцы каллиграфии и красные печати коллекционеров заполняют небо над вершинами."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DWELLING_IN_THE_FUCHUN"] =
    "Китайский свиток тушью, шедевр пейзажной живописи учёных-литераторов эпохи Юань, исполненный целиком в оттенках чёрной туши на бумаге. Округлые горы, выстроенные из слоёв сухих мазков кисти, поднимаются над широкой спокойной рекой, а по берегам стоят сосны, разбросанные хижины и рыбацкие лодки. Настроение неспешно и созерцательно; бумага усеяна красными печатями коллекционеров, накопившимися за века почитателей."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ALONG_THE_RIVER"] =
    "Китайский свиток на шёлке эпохи Сун, знаменитая панорама повседневной городской жизни длиной свыше пяти метров. Показанный фрагмент сосредоточен на больших городских воротах столицы: это массивная деревянная башня на покатом валу, а внизу кипят жизнью улицы с рыночными лотками, воловьими повозками, проходящим через ворота караваном верблюдов и носильщиками, несущими грузы на коромыслах. Каждая фигура крошечна, но выписана точной тонкой тушевой линией в приглушённых землистых тонах."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LEAF_2"] =
    "Китайский альбомный лист эпохи Цин, придворная живопись тонкой линией и нежным цветом. Изящные дамы в длинных струящихся одеяниях белого, зелёного и синего цвета собрались в садовом павильоне, задрапированном ярко-синей тканью; одна из них воскуривает благовония у стола за красными перилами. Вокруг них садовые камни, бамбук и цветущая лиана, вьющаяся по крыше павильона."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EMPEROR_TAIZONG"] =
    "Китайский свиток на шёлке эпохи Тан, придворная запись дипломатической встречи. Справа император Тайцзун сидит на помосте, который несут придворные дамы; они же держат над ним два больших опахала и красный балдахин. Слева в почтительных позах приближаются три фигуры поменьше: придворный церемониймейстер в красном, тибетский посол в узорчатом халате и переводчик в белом, и все они на фоне тёплого золотистого шёлка, покрытого красными печатями."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SPRING_MORNING"] =
    "Китайский свиток на шёлке эпохи Мин, длинная панорама дворцовых женщин на досуге весенним утром. Десятки изящных дам заполняют открытые залы, веранды и дворы: они музицируют, пишут портрет, играют с детьми и прогуливаются среди ив, садовых камней и даже павлинов. Дворцовая архитектура тянется во всю длину свитка тёплыми красными и зелёными тонами, и каждая ширма, перила и одеяние переданы с дотошной тонколинейной детальностью."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_GREAT_WAVE"] =
    "Японская гравюра укиё-э на дереве, самое знаменитое изображение в японском искусстве. Огромная тёмно-синяя волна вздымается слева и нависает над всей сценой, её гребень разбивается на когтистые пальцы белой пены. Под ней три длинные открытые лодки, полные гребцов, идут по впадинам волн, а далеко в глубине, крошечная в самом центре всего, виднеется заснеженный конус горы Фудзи."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EVENING_SHOWER"] =
    "Японская гравюра укиё-э на дереве, одна из самых ценимых сцен дождя из когда-либо созданных. Внезапный ливень, прорисованный как пелена тонких косых линий, застаёт людей на середине длинного деревянного моста; они спешат в обе стороны под шляпами и зонтами, а один укрывается под соломенной циновкой. Река внизу - полоса бирюзы, по которой в одиночку правит шестом плотогон, а дальний берег под бурей растворяется в тёмное пятно."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_L_ABSINTHE"] =
    "Французская импрессионистская картина маслом, безжалостная сцена парижской кафейной жизни. Женщина в бледном платье и шляпе сидит, поникнув, за мраморным столиком кафе, опустив глаза, а перед ней стоит бокал молочно-зелёного абсента; рядом с ней бородатый мужчина в помятом пальто смотрит куда-то вправо с трубкой во рту. Эти двое сидят вместе и всё же совершенно порознь, написанные в тусклых серых и коричневых тонах, что несут в себе общее настроение одиночества картины."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_UPAUPA_SCHNEKLUD"] =
    "Постимпрессионистский портрет маслом, изображающий виолончелиста во время игры. Музыкант склонился над своей ярко оранжево-красной виолончелью, опустив глаза в сосредоточении; рука со смычком скользит по струнам, а его тёмно-синий костюм обрамляет свечение инструмента. Позади него фон распадается на плоские зоны коричневого и мшисто-зелёного, усеянные бледными абстрактными формами, в смелой, упрощённой цветовой манере Гогена."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_A_BAR_AT_THE_FOLIES"] =
    "Французская масляная картина из современной жизни, последняя большая работа Мане. Барменша в чёрном бархатном корсаже с цветком у груди стоит за мраморной стойкой, заставленной бутылками шампанского, чашей с апельсинами и бокалом с розой, и глядит перед собой с усталым, отсутствующим выражением. За её спиной огромное зеркало отражает сверкающий мюзик-холл с люстрами и толпой, а также, странно смещённую вправо, её собственную спину, когда она склоняется к мужчине в цилиндре."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BALL_AT_THE_MOULIN"] =
    "Постимпрессионистская масляная картина парижской ночной жизни в знаменитом кабаре. Группа мужчин в цилиндрах и женщин в шляпах с перьями сидит вокруг стола с напитками, а позади них рыжеволосая женщина поправляет причёску в зелёном свете танцевального зала. У правого края лицо женщины надвигается на смотрящего, освещённое призрачно-зелёным светом снизу, и длинные диагональные перила рассекают передний план в плакатной манере Лотрека."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_KISS"] =
    "Венская масляная картина в стиле модерн, покрытая слоями настоящего сусального золота, самая знаменитая работа Климта. Пара стоит на коленях, слитая в объятии, на цветущем лугу; мужчина склоняется, чтобы поцеловать женщину в щёку, а она запрокидывает лицо с закрытыми глазами. Их тела сливаются в единый золотой плащ, узор которого складывается из прямоугольников для него и ярких кругов для неё, сияя на плоском мерцающем золотом фоне."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_AMERICAN_GOTHIC"] =
    "Масляная картина американского регионализма, бесконечно пародируемая и узнаваемая с первого взгляда. Суровый лысеющий фермер в круглых очках и джинсовом комбинезоне стоит, держа вертикально трёхзубые вилы; рядом женщина в тёмном платье-фартуке с набивным узором смотрит в сторону с поджатыми губами и неодобрением. За ними белый фермерский дом, давший название картине, с остроконечным готическим окном в щипце."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SRI_SHANMUKAHA"] =
    "Индийская религиозная картина в европейском академическом стиле, который Рави Варма прославил по всей Индии. Индуистский бог Муруган едет верхом на своём павлине, с шестью увенчанными коронами головами и множеством рук, держащих оружие; по сторонам от него две его супруги в ярко-розовых сари. Павлиний хвост раскрывается за их спинами, как гигантский веер из зелёных и золотых глазков, а сама птица придавливает лапами кобру."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DAUD_RECEIVES_A_ROBE"] =
    "Могольская миниатюра из иллюстрированной императорской хроники, выполненная непрозрачной акварелью и золотом по бумаге. Показанный фрагмент сосредоточен на стройном юном слуге в бледном одеянии, красной шапочке и золотом кушаке, который несёт сложенный золотой почётный халат для церемонии вручения. Он стоит на фоне яркой синей стены шатра, покрытой тонкими цветущими побегами, где каждая складка и каждый цветок написаны с миниатюрной точностью."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_YUSEF_AND_ZULEYKHA"] =
    "Персидская миниатюра из иллюстрированной рукописи, самая прославленная работа великого гератского мастера Бехзада. Лист заполнен затейливым дворцом, показанным в уплощённом разрезе, лабиринтом лестниц, балконов и дверных проёмов, выложенных синей, оранжевой и золотой плиткой. В верхнем покое пророк Юсуф, окружённый огненным ореолом, бежит от простёртых к нему рук Зулейхи, а полосы персидской каллиграфии обрамляют архитектуру."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_ASCENT_OF_MUHAMMAD"] =
    "Персидская миниатюра из царской рукописи, изображающая ночное путешествие Пророка по небесам. Мухаммед, чьё лицо скрыто белым покрывалом и окружено золотым пламенем, едет на человекоголовом скакуне Бураке по глубокому синему небу, усеянному вьющимися облаками с золотой каймой. Ангелы в одеяниях красного, зелёного и оранжевого цвета кружат вокруг него со всех сторон, неся дары и кадильницы, а строки персидских стихов обрамляют сцену."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LIBERTY_LEADING_THE_PEOPLE"] =
    "Французская романтическая масляная картина, главный образ революции. Сама Свобода, женщина с обнажённой грудью в жёлтом платье и красном колпаке, шагает через баррикаду из обломков и павших тел, вздымая французский триколор в задымлённое небо. Вокруг неё напирают вооружённые горожане всех сословий, среди них джентльмен в цилиндре с мушкетом и мальчик, размахивающий двумя пистолетами."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_JEROME_IN_HIS_STUDY"] =
    "Масляная картина раннего Возрождения замечательной миниатюрной точности. Сквозь величественную каменную арку видно, как Святой Иероним в красном облачении сидит и читает за деревянной кельей, выстроенной словно сцена внутри сводчатого пространства собора, в окружении полок с книгами и сосудами. Свет льётся из окон со всех сторон, павлин и куропатка сидят на пороге впереди, а его лев крадётся в тени справа."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PARTHENON_FRIEZE"] =
    "Викторианская масляная картина, представляющая древние Афины; в игре эта работа прилагается к чуду света Парфенон. Скульптор Фидий стоит на деревянных лесах рядом со своим только что расписанным мраморным фризом с всадниками, ещё в мастерских красках, и придерживает верёвку, представляя его. Небольшая группа афинян в драпированных одеждах, среди них Перикл, склоняется, чтобы рассмотреть резьбу в тёплом свете внутри храма."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_RUE_DE_PARIS"] =
    "Французская реалистическая масляная картина современного Парижа в дождливый день, чёткая и фотографичная там, где его друзья-импрессионисты писали свободно. Хорошо одетая пара под общим зонтом идёт навстречу смотрящему по блестящей брусчатке; мужчина в цилиндре, а женщина в длинном тёмном платье, и её серьга ловит свет. Вокруг них другие прохожие с зонтами пересекают широкий перекрёсток, обрамлённый клиновидными серыми жилыми домами, а зелёный фонарный столб делит сцену посередине."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_NIGHT_WATCH"] =
    "Голландская масляная картина золотого века огромного размера, самый знаменитый групповой портрет из когда-либо написанных. Городская стрелковая рота вырывается в движение из глубокой тени: капитан в чёрном с красной перевязью шагает вперёд, отдавая приказ своему лейтенанту в бледно-золотом, а позади них заряжают мушкеты, поднимают знамя и барабанщик отбивает такт. Маленькая девочка в сияющем золотом платье таинственно светится в толпе, освещённая, словно прожектором, во мраке."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DEATH_OF_MARAT"] =
    'Французская неоклассическая масляная картина, великий образ мученика Французской революции. Революционный журналист Марат лежит мёртвым в своей ванне, обмякший, как павший святой, голова обёрнута белым тюрбаном, одна рука свисает к полу, всё ещё сжимая перо. В другой руке письмо, с помощью которого его убийца проник к нему; верхняя половина холста занята голой тёмной стеной, а на простом деревянном ящике рядом с ним написано посвящение "A Marat, David."'
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ETIENNE_CHEVALIER"] =
    "Французская позднесредневековая живопись на доске, одна створка знаменитого молитвенного диптиха. Королевский казначей Этьен Шевалье преклонил колени в богатом красном облачении, молитвенно сложив ладони; его представляет покровитель Святой Стефан, стоящий рядом в сине-золотом облачении. Святой держит книгу, поверх которой лежит зазубренный камень, символ его мученичества, и оба стоят в белом мраморном зале, вдоль стены которого высечено имя заказчика."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_FRANCIS"] =
    "Испанская барочная картина маслом суровой монашеской набожности. Святой Франциск стоит в одиночестве в простом капюшонном облачении песочного цвета, его лицо наполовину утопает в глубокой тени капюшона, глаза опущены в молитве. Он держит в ладонях человеческий череп как напоминание о смерти, освещённый единственным жёстким светом на почти чёрном фоне."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HATAORI"] =
    "Японская ксилография укиё-э, изображающая ткачиху за работой. Молодая женщина в узорчатом кимоно цвета индиго сидит босиком за большим деревянным ручным ткацким станком, отрываясь от работы и держа в одной руке челнок; нити красного, синего и белого цвета натянуты вдоль всего станка. Краски мягкие кремовые и приглушённые синие, а столбец написанной кистью поэзии заполняет верхний левый угол листа."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_JANE_GREY"] =
    "Французская академическая историческая картина, театральная и душераздирающая. Юная королева с завязанными глазами, в белом атласе, сияющем на фоне тёмной каменной камеры, преклонила колени и вслепую нащупывает плаху, а пожилой сановник мягко направляет её руки к ней. Её придворные дамы в горе оседают у колонны за её спиной, а палач ждёт справа, опершись на топор и отведя взгляд."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_WANDERER"] =
    "Немецкая романтическая картина маслом, главный образ человека наедине с природой. Молодой мужчина в тёмно-зелёном сюртуке стоит спиной к смотрящему на скалистой вершине, опираясь на трость, его волосы развевает ветер. Под ним океан белого тумана поглощает долину, и лишь гребни и утёсы пробиваются сквозь него, словно острова, а бледные горы тают вдали."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BABEL"] =
    "Фламандская ренессансная картина маслом, изображающая обречённую библейскую башню и кишащая подробностями. Колоссальная спиральная башня из арок, частью из белого камня, частью из необработанного красного кирпича, кособоко поднимается в облака, и вершина её ещё незавершена. У её подножия раскинулся портовый город с кораблями на якоре, а на переднем плане царь осматривает артель каменщиков, которые преклонили колени у его ног среди своих блоков."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_YOUNG_LADY"] =
    "Ранненидерландский портрет маслом, маленький, неподвижный и странно современный. Бледная молодая женщина с гладким, как фарфор, лицом смотрит на смотрящего искоса из-под высокого головного убора из чёрного бархата, отделанного золотом. На ней синее платье с белым меховым воротником и тесное ожерелье из золотых и чёрных полос, на фоне простой тусклой стены, а не обычной тёмной пустоты."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_KINDRED"] =
    "Американская картина маслом школы реки Гудзон, дань дружбе живописца и поэта. Двое мужчин в сюртуках стоят и беседуют на каменном уступе, нависающем над лесистым ущельем в горах Катскилл, и один указывает кистью на вид. Внизу ручей перекатывается по камням в обрамлении арки нависающих деревьев, а позади дымчатые вершины растворяются в золотом свете."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BLUE_BOY"] =
    "Английский портрет маслом в большом стиле, самая знаменитая работа художника. Мальчик лет двенадцати стоит в полный рост в мерцающем костюме из синего атласа с короткими штанами и кружевным воротником, одна рука на бедре, в другой он держит у бока шляпу с плюмажем. Он смотрит с непринуждённой уверенностью на фоне тёмного грозового бурого пейзажа, на котором синий наряд пылает."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SECOND_OF_MAY"] =
    "Испанская картина маслом, один из первых и величайших протестов против войны в искусстве. При свете фонаря французский расстрельный отряд стоит безликим рядом, винтовки наведены на сгрудившихся испанских пленников на голом холме за пределами Мадрида. В центре мужчина в белой рубахе раскидывает руки перед ружьями, стоя на коленях среди тел уже расстрелянных, и его поза перекликается с распятием."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LAST_CART"] =
    "Французская военная картина маслом времён франко-прусской войны, знаменитый образ дерзкого последнего сопротивления. Горстка французских солдат обороняет разрушенный деревенский дом, стреляя из окна, тогда как раненые сидят, осев у стен, а офицер пересчитывает их последние патроны. Комната разгромлена, дверь сорвана с петель, с потолка осыпается штукатурка, дневной свет заливает дверной проём, где продолжают сражаться товарищи."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EARLY_AUTUMN"] =
    "Китайский горизонтальный свиток тушью и мягкими красками, крупный план природы увядающего лотосового пруда. Стрекозы красного, зелёного и синего цвета парят над сохнущим тростником и потрёпанными листьями лотоса, а внизу заняты своими делами кузнечики, пчела и маленькие лягушки. Настроение - тихое увядание, продолжающаяся жизнь лета среди растений, только начинающих чахнуть; вдоль обоих краёв стоят красные печати коллекционеров."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_APPRECIATING_LOTUSES"] =
    "Японский висячий свиток тушью и красками работы основателя школы Кано, написанный в манере китайского пейзажа учёных. Облачённый китайский учёный плывёт в маленькой лодке у края лотосового пруда, глядя на плавающие листья под узловатой ивой, склонившейся над скалистым берегом. Большую часть высокого свитка занимают дымка и открытая вода, и лишь несколько верхушек сосен растворяются в мареве."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EQUESTRIAN_PORTRAIT"] =
    "Венецианская ренессансная картина маслом, образец для веков изображений правителей верхом. Император Священной Римской империи выезжает из тёмного леса в сияющих доспехах, в шлеме с красным плюмажем и с копьём в руке, в память о его победе при Мюльберге. Его вороной конь укрыт алой попоной, а низкое вечернее солнце пробивается золотом и розовым под тяжёлыми грозовыми облаками."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_ARMADA"] =
    "Тюдоровский пропагандистский портрет маслом, написанный в честь разгрома Непобедимой армады. Королева Елизавета сидит в необъятном платье из жемчуга и бантов, её лицо обрамлено широким белым кружевным воротником, одна рука властно покоится на глобусе, пальцы лежат на Америке. В окнах за её спиной история разворачивается дважды: с одной стороны английский флот в спокойном море, с другой испанские корабли, разбитые бурей. Рядом с ней лежит её украшенная самоцветами корона."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_FRANCIS_I"] =
    "Французский ренессансный королевский портрет маслом. Король обращён к смотрящему по пояс, в роскошном придворном наряде: разрезные рукава из белого и золотого атласа в чёрную полоску, золотая цепь поперёк груди, на голове чёрный берет с белым плюмажем. Его лукавое бородатое лицо с длинным носом выделяется на фоне малинового камчатого узора с коронами."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SELF_PORTRAIT"] =
    "Автопортрет маслом в духе северного маньеризма, написанный фламандским придворным живописцем императора Рудольфа II. Художник оглядывается на смотрящего через плечо, это крепкий бородатый мужчина с курчавыми волосами под мягкой чёрной шапочкой, в белом гофрированном воротнике поверх серо-голубого дублета. Письмо тёплое и прямое, на простом коричневом фоне, а его оценивающий взгляд искоса не отпускает."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_VERTUMNUS"] =
    "Картина маслом в духе маньеризма, самая знаменитая из фантастических составных голов Арчимбольдо. Это портрет императора Рудольфа II в образе римского бога времён года, чьё лицо и грудь целиком собраны из фруктов, овощей и цветов: веки из стручков гороха, нос из груши, губы из вишен, бакенбарды из колосьев пшеницы и волосы из винограда. Издали это величавый правитель, вблизи он рассыпается в торговый прилавок, и всё это на чёрном фоне."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LAST_SUPPER"] =
    "Венецианская картина маслом позднего Возрождения, заново переосмысливающая знакомую сцену. Вместо того чтобы быть обращённым к смотрящему прямо, стол с трапезой уходит вглубь по крутой диагонали в тёмный зал таверны, и на середине его длины светится Христос, протягивающий апостолам хлеб. Слуги тащат еду, а кошка суёт нос в корзину на переднем плане, тогда как пылающая масляная лампа наполняет дымный воздух наверху прозрачными вьющимися ангелами."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_A_MAN"] =
    "Ранненидерландская картина маслом, возможно, собственное лицо художника и один из первых настоящих автопортретов. Мужчина средних лет с морщинистым, остроглазым лицом смотрит прямо на смотрящего из глубокой тени, на нём пышный красный головной убор, обмотанный и завязанный в скульптурные складки. Детализация тончайшая, передана каждая морщина и каждый волосок щетины, а сама фигура в тёмном плаще с меховой опушкой на чёрном фоне."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_FRONT_OF_THE_MIRROR"] =
    "Венецианская ренессансная картина маслом, безмятежный поздний шедевр престарелого Беллини. Обнажённая молодая женщина с рыжевато-каштановыми волосами сидит на красной ткани, спокойно поправляя причёску и держа небольшое ручное зеркальце, а второе круглое зеркало на стене позади отражает узорчатый головной убор сзади. Окно рядом с ней открывается на зелёную сельскую местность с далёкими синими горами под облачным небом."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ADORATION"] =
    "Ранняя итальянская фреска из капеллы Скровеньи, написанная живописцем, которому приписывают возвращение естественного человеческого чувства в западное искусство. Под деревянным навесом Мария держит младенца Христа, а старший из трёх волхвов преклоняет колени, чтобы поцеловать стопы дитяти, отложив в сторону свою корону; слева ждут верблюды. Над хлевом по тёмно-синему небу вместо привычной звезды чертит свой путь комета, и всё это в плотных, простых фигурах Джотто и ясных красках."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_RUBENS_AND_ISABELLA"] =
    "Фламандская барочная картина маслом, свадебный портрет художника с самим собой и невестой. Молодая чета сидит близко друг к другу под кустом жимолости, её правая рука нежно покоится поверх его руки, и это тихий центр картины. Он сидит выше её в чёрном дублете, заложив ногу за ногу, она опустилась на колено в фиолетовой юбке, золотошитом корсаже, широком воротнике и высокой соломенной шляпе, оба глядят наружу со спокойным довольством."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CHILDS_BATH"] =
    "Американская импрессионистская картина маслом о повседневной нежности, на которую повлияли японские гравюры своей высокой точкой обзора и плоскими узорами. Мать в смело полосатом платье держит на коленях ребёнка, завёрнутого в полотенце, и моет малышу ноги в тазу с водой. Обе головы склоняются вместе над этим занятием, а комната вокруг них словно лоскутное одеяло из узоров: цветастые обои, расписной сундук, нарядный ковёр и белый кувшин."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_CARD_PLAYERS"] =
    "Постимпрессионистская картина маслом, одна из знаменитой серии на этот сюжет. Двое крестьян в шляпах сидят лицом друг к другу за маленьким деревянным столом, поглощённые своими картами, а единственная бутылка вина стоит между ними как неподвижный центр композиции. Один курит трубку; краска положена терпеливыми, угловатыми мазками землистого коричневого, охры и приглушённого фиолетового, отчего фигуры кажутся изваянными и незыблемыми."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_SWING"] =
    "Французская картина маслом в духе рококо, легкомысленная, полная тайны и самый знаменитый образ эпохи. В пышном заросшем саду молодая женщина в воздушном розовом платье взлетает высоко на качелях, сбрасывая в воздух одну туфельку, а скрытый в тени позади неё пожилой мужчина тянет верёвки. Её юный возлюбленный раскинулся внизу среди розовых кустов, идеально расположенный, чтобы заглянуть ей под юбки, а каменная статуя купидона подносит палец к губам."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GIANT_MAGNOLIAS"] =
    "Американский натюрморт маслом, пышный и почти тропический по ощущению. Два огромных кремово-белых цветка магнолии лежат срезанными на драпировке из тёмно-синего бархата, окружённые своими глянцевыми тёмными листьями, рядом третий, ещё закрытый бутон. Лепестки светятся на почти чёрном фоне, написанные с восковой, чувственной точностью."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_GEORGE_KILLING"] =
    "Каталонская готическая панельная роспись темперой и золотом. Святой Георгий, в чёрных доспехах и с золотым нимбом, склоняется со своего вздыбленного белого коня, чтобы вонзить длинное копьё в разверстую пасть крылатого, как летучая мышь, дракона, а земля вокруг них усеяна костями и черепами. Принцесса в розовом платье молится на скалистом уступе позади, а зрители теснятся на белых стенах замка наверху."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_JACQUES_AND_BERTHE"] =
    "Модернистский парный портрет маслом, изображающий скульптора Липшица и его жену, написанный в безошибочно узнаваемой манере Модильяни. Муж стоит в тёмном костюме, положив руку на плечо сидящей жены, чьё румяное лицо поднимается над белым кружевным воротником. У обоих фирменные для художника удлинённые лица, длинные носы и пустые миндалевидные глаза, а их имена нацарапаны поверху холста."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DASH_FOR_TIMBER"] =
    "Картина маслом в духе американского Запада, та самая стремительная батальная сцена, что определила образ Дикого Запада в народном воображении. Восемь ковбоев скачут прямо на вас во весь опор, копыта лошадей оторваны от земли, двое всадников развернулись в сёдлах, отстреливаясь от отряда конных апачей, преследующих их в пыли позади. Один раненый осел, привалившись к товарищу, пока они несутся к деревьям у левого края сухой равнины."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GEORGE_WASHINGTON_PORTRAIT"] =
    "Американский парадный портрет маслом, официальный образ первого президентства. Вашингтон изображён в полный рост в простом чёрном бархатном костюме, одна рука вытянута в ораторском жесте, другая держит парадную шпагу, рядом стоит стол с пером и чернильницей. Окружающая его обстановка - это республиканское величие: золочёное кресло со щитом в звёздах и полосах, мраморные колонны и алая драпировка, а за ней сквозь грозовые тучи пробивается радуга."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ATTACK_ON_BEIJING"] =
    "Японская цветная гравюра в стиле военной репортажной иллюстрации, с подписями на японском и английском. Союзные войска штурмуют стены императорского дворца в Пекине: британские солдаты в красных мундирах с флагом Юнион Джек идут в атаку на переднем плане, а японская пехота в белых мундирах наступает справа. Разрывы снарядов висят белыми клубами над зелёным плацем, а позади видны синяя крыша дворцовых ворот и дымящиеся стены."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SUMO_WRESTLER"] =
    "Японская гравюра укиё-э на дереве, портрет прославленного борца на отдыхе. Грузный мужчина изображён во весь рост в чёрном кимоно поверх узорчатых одежд, мечи у пояса, он промокает лоб клетчатой тканью, неся свёрнутый плащ на одном плече. Его имя идёт сверху вниз по правому краю жирными красными каллиграфическими панелями, а сама фигура плоская и монументальная на фоне чистой бумаги."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_TIGER_IN_TROPICAL_STORM"] =
    "Картина маслом в наивном стиле работы самоучки, французского таможенного служащего, никогда не видевшего джунглей. Тигр с широко раскрытыми глазами припал к земле в высокой траве, изогнутой ветром, оскалив зубы, застигнутый бурей, которая клонит набок каждое растение. Джунгли - это плотный узор стилизованных листьев в зелёных и красных тонах, а по всему холсту наискось проведены серебристые струи дождя, словно газовая вуаль."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_HOME_GUARD"] =
    "Венгерский портрет маслом в стиле бидермейер времён революции 1848 года. Бородатый гражданин-ополченец сидит в простой куртке из некрашеного льна, обе руки в перчатках лежат на эфесе поставленной вертикально сабли, а красно-бело-зелёная национальная повязка на рукаве объявляет, на чьей он стороне. Он смотрит в сторону со спокойной решимостью, освещённый тёплым светом на фоне тёмно-красного занавеса, а его подбитый красным мундир переброшен через кресло."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CEREMONIAL_SITTING"] =
    "Русская реалистическая картина маслом огромного масштаба, групповой портрет всего правящего совета империи. Десятки пожилых государственных мужей в тёмных мундирах, тяжёлых от золотого шитья, и красных лентах сидят вокруг большой подковы из красных кресел в белоколонном зале с люстрами и царскими портретами. Каждое из более чем шестидесяти лиц - это отдельный портрет, написанный быстрым, уверенным реализмом Репина."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_RUSSIAN_TSAR"] =
    "Русская историческая картина маслом, воссоздающая царское шествие шестнадцатого века. Царь в меховой шапке и одеянии из золотой парчи едет на белом коне по снегу, а впереди него идут стражники в ярко-красных кафтанах с высокими изогнутыми бердышами. Толпа стоит на коленях и кланяется до земли по обе стороны истоптанной снежной дороги, а под бледным зимним небом видны бревенчатые постройки старого русского города."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CRUCIFIXION_OF_SAINT_PETER"] =
    "Итальянская картина маслом в стиле барокко, жестокая и телесная, в характерной манере Караваджо. Трое работников силятся поднять деревянный крест, на котором был распят вниз головой старый святой Пётр, один тянет за верёвку, другой пригнулся под перекладиной, лица их скрыты. Седобородый святой поднимает голову, чтобы взглянуть на собственную пробитую гвоздём руку, его мускулистое старческое тело пылает, выступая из кромешной тьмы в одном резком луче света."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LANDSCAPE_WITH_ANT_BEAR"] =
    "Голландский колониальный пейзаж маслом, написанный первым художником с европейской выучкой, работавшим в Бразилии. Широкая залитая солнцем долина с рекой раскрывается под огромным небом между двумя высокими пальмами, а на дальних холмах виднеется колониальное поселение из белых домов. Группа афробразильцев идёт по тропе на переднем плане, неся узлы, а длиннорылый муравьед, вынесенный в название, роется в кустарнике в правом нижнем углу."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DUTCH_MEN_O_WAR"] =
    "Голландская марина маслом эпохи Золотого века, написанная величайшим в ту пору живописцем кораблей. Высокие деревянные военные корабли стоят на якоре на гладкой как стекло воде, их паруса висят вяло, а корпуса отражаются в море, и каждая линия снастей выписана точно. Лодки перевозят пассажиров между судами под огромным небом с залитыми солнцем кучевыми облаками, и вся сцена омыта золотым покоем."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HARBOR_IN_BALAKLAVA"] =
    "Тонированная литография времён Крымской войны, выполненная одним из первых военных художников, документировавших кампанию на месте событий. На унылом берегу гавани больных и раненых солдат, закутанных в белые одеяла, переносят с навьюченных на мулов носилок в ожидающую лодку. Голые бурые холмы поднимаются позади скопления фигур, а по склону рассыпаны армейские бараки и палатки, цвета приглушены и документальны."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PEACEMAKERS"] =
    "Американская историческая картина маслом, изображающая реальный военный совет последних дней Гражданской войны. Президент Линкольн сидит в каюте парохода, напряжённо слушая, подперев подбородок рукой, пока генерал Шерман жестикулирует посреди спора, а генерал Грант и адмирал Портер замыкают круг из четырёх фигур в тёмных костюмах. Сквозь окна каюты позади них в проясняющемся небе пробивается радуга, тихий знак приближающегося мира."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_CHITASEI"] =
    "Японская гравюра укиё-э на дереве из знаменитой серии Куниёси, посвящённой 108 героям китайского романа Речные заводи. Учёный-стратег У Юн стоит в развевающемся тёмном одеянии с узором из драконов, в задумчивости поглаживая бороду под ночным небом, усыпанным звёздами. Рядом с ним на вычурной подставке стоит большой небесный глобус, а фигуру обрамляют панели с японским текстом."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_LOUIS"] =
    "Английский масляный портрет восемнадцатого века, скульптор застигнут за работой. Рубильяк в мягком колпаке и распахнутой рубашке с закатанными рукавами замер с поднятым в руке стеком, глядя в сторону и работая над глиняной статуэткой Шекспира на подставке. Свободной рукой скульптор указывает на собственное творение; он тепло освещён на фоне тёмной мастерской."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_NASSER"] =
    "Персидский каджарский придворный портрет маслом, царское великолепие положено густым слоем. Молодой усатый шах сидит, выпрямившись с напряжённой неподвижностью, в алом мундире, расшитом золотом, в нитях жемчуга, с усыпанными самоцветами эполетами и синей перевязью, одна рука лежит на украшенной драгоценными камнями сабле. На нём высокая чёрная шапка с пучком бриллиантов, его обведённые тёмным глаза смотрят прямо на фоне глубокого оливкового поля с оттиснутой царской надписью."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_FIELD_WITH_SHEAFS"] =
    "Пейзаж маслом с уклоном в немецкий экспрессионизм, написанный широкими, энергичными мазками. Сжатое пшеничное поле заполняет передний план рядами золотых снопов, составленных в накренённые скирды, жёлтый цвет положен густо и ярко. Полоса тёмно-зелёных деревьев замыкает поле, а над ним бледное фиолетово-синее небо с ветреными облаками."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_AT_THE_EDGE_OF_THE_BROOK"] =
    "Французская академическая картина маслом, отполированная до гладкого совершенства, которым славился Бугро. Двое босых крестьянских детей сидят на камне на берегу ручья, девочка помладше стягивает чулок, а её темноволосая спутница подбирает юбку, чтобы войти в воду. Они переглядываются посреди разговора, их кожа и растрёпанные волосы написаны с фотографической гладкостью на фоне мягкого сельского пейзажа."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_KISS_ALT"] =
    "Итальянская романтическая картина маслом, самый знаменитый поцелуй в итальянском искусстве и скрытый патриотический символ объединения страны. В средневековом каменном коридоре молодой человек в шляпе с пером и коричневом плаще склоняет женщину назад в страстном поцелуе, одна нога уже на ступени, словно он замер на бегу. Её платье из бледно-голубого атласа изливает свет в сцену, а сквозь арку в глубине приближается тёмная фигура."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MOVING_HOUSE"] =
    "Русская реалистическая картина маслом о тихой городской бедности. Пожилая пара бредёт по замёрзшему льду реки в Санкт-Петербурге, неся всё своё имущество в узле из ткани, мужчина опирается на трость, оба закутаны в изношенные пальто и платки от холода. Впереди них бежит маленькая собачка, а сквозь зимнюю дымку позади поднимается золочёный шпиль Петропавловской крепости."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MEXICAN_EXPEDITION"] =
    "Французская морская историческая картина маслом, в репортажной манере и полная действия. Французский военный корабль под триколором главенствует в левой части переднего плана, офицеры на его палубе руководят бомбардировкой мексиканской крепости Сан-Хуан-де-Улуа, над водой поднимается дым. Снаряды падают рядом с гребными шлюпками, перевозящими людей между кораблями, а на туманном горизонте виднеется покрытый снегом вулкан."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LAST_DAY_OF_POMPEII"] =
    "Русская романтическая картина маслом на огромном холсте, катастрофический эпос своего века. Небо над Помпеями горит красным и чёрным в час извержения Везувия, статуи рушатся с крыши, и молния рассекает облако пепла. Толпы горожан в римских одеждах бегут сквозь падающие обломки, укрывая под плащами детей и стариков, а в центре упавшая женщина распростёрта возле опрокинутой колесницы."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_ACCOLADE"] =
    "Английская картина маслом в духе прерафаэлитов, сказочное видение рыцарства. Златовласая королева в струящемся белом платье касается мечом плеча коленопреклонённого рыцаря, посвящая его перед небольшим придворным собранием. Он склоняет голову, в кольчуге и красной налатной рубахе, его шлем лежит на полу рядом, а каменный зал и красный помост написаны в сияющих романтических подробностях."
